c.java:
class Solution {
    public int smallestRangeI(int[] nums, int k) {
        int mx = Integer.MIN_VALUE, mn = Integer.MAX_VALUE;
        for (int x : nums) {
            mx = Math.max(mx, x);
            mn = Math.min(mn, x);
        }
        return Math.max(0, mx - mn - 2 * k);
    }
}

